    {
        return SMTC_MODEM_RC_INVALID;
    }

    if( smtc_modem_join_network( stack_id ) != SMTC_MODEM_RC_OK )
    {
        return SMTC_MODEM_RC_FAIL;
    }
    return SMTC_MODEM_RC_OK;
}

