    	&& (lr1_mac_obj->is_lorawan_modem_certification_port_deactivated))
    {
    	lr1_mac_obj->is_lorawan_modem_certification_port_deactivated = 0;
    	lr1mac_core_context_save(&lr1_mac_obj[stack_id]);
    	return 1;
    }
    return 0;
}

