        id = LR11XX_CRYPTO_KEYS_IDX_GP0;
        break;
    default:
        id = LR11XX_CRYPTO_KEYS_IDX_GP1;
        break;
    }
    return id;
}

uint32_t lr11xx_ce_crc( const uint8_t* buf, int len )
{
    uint32_t crc = 0xFFFFFFFF;
    while( len-- > 0 )
    {
        crc = crc ^ *buf++;
        for( int i = 0; i < 8; i++ )
        {
            uint32_t mask = -( crc & 1 );
            crc           = ( crc >> 1 ) ^ ( 0xEDB88320 & mask );
        }
    }
    return ~crc;
}
