    stream_ctx_t* ctx = stream_get_ctx_from_stack_id( stack_id, &service_id );
    SMTC_MODEM_HAL_PANIC_ON_FAILURE( ctx != NULL );
    return ctx->is_stream_init;
}

bool stream_get_status( uint8_t stack_id )
{
    IS_VALID_STACK_ID( stack_id );
    uint8_t       service_id;
