status_lorawan_t lr1_stack_nb_trans_set( lr1_stack_mac_t* lr1_mac, uint8_t nb_trans )
{
    if( lr1_mac->adr_mode_select == STATIC_ADR_MODE )
    {
        return ERRORLORAWAN;
    }

    if( ( nb_trans > 0 ) && ( nb_trans < 16 ) )
    {
        lr1_mac->nb_trans = nb_trans;
        return OKLORAWAN;
    }

    return ERRORLORAWAN;
}

