    uint8_t                stack_id;
} lr1_stack_mac_down_data_t;
typedef struct lr1_stack_mac_s
{
    smtc_real_t*        real;  // Region Abstraction Layer
#ifdef RELAY
    smtc_lbt_t*         lbt_obj;
    smtc_lora_cad_bt_t* cad_obj;
#endif
    void ( *push_callback )( lr1_stack_mac_down_data_t* );
    void* push_context;

    /* LoraWan Context */

    /*******************************************/
    /*      Update by Link ADR command         */
    /*******************************************/
