    smtc_dtc_t* dtc_obj_ptr;
#if defined( REGION_EU868 ) || defined( REGION_RU864 )
    smtc_dtc_t dtc_obj_ctx;
#endif
} dtc_context;
#define dtc_obj_ptr dtc_context.dtc_obj_ptr
#define dtc_obj_ctx dtc_context.dtc_obj_ctx

