                      const uint8_t wor_s_enc_key[16] )
{
    uint8_t tmp[3];
    wor_aes_ack_uplink_enc( buffer + WOR_ACK_PAYLOAD_ENC_1, tmp, mic_infos, wor_s_enc_key );
