    CAD_STATE_WAIT_CAD_COMPLETION,
    CAD_STATE_WAIT_WOR_COMPLETION,
    CAD_STATE_WAIT_TX_ACK_COMPLETION,
    CAD_STATE_WAIT_RX_DATA_COMPLETION,
} cad_state_t;

