void smtc_relay_tx_enable( uint8_t relay_stack_id );

/**
 * @brief Check if WOR is enable before LoRaWAN Uplink
 *
 * @param[in]   relay_stack_id  relay stack id
 * @return true     WOR is enable before LoRaWAN Uplink
