    FRAGMENTATION_SESSION_DELETE_REQ      = 0x03,
    FRAGMENTATION_DATA_BLOCK_RECEIVED_REQ = 0x04,
    FRAGMENTATION_DATA_FRAGMENT           = 0x08,
} fragmented_package_req_t;

