    sum += (_Float16)(*pSrcA++) * (_Float16)(*pSrcB++);

    sum += (_Float16)(*pSrcA++) * (_Float16)(*pSrcB++);

    sum += (_Float16)(*pSrcA++) * (_Float16)(*pSrcB++);

