            vecDst = vqdmladhxq_m(vecDst, vecSrcA, vecSrcB, p);

            vecDst = vshrq_m(vuninitializedq_s32(), vecDst, 2, p);
            vstrwq_p_s32(pDst, vecDst, p);

            pDst += 4;
            pSrcA += 4;
            pSrcB += 4;

            blkCnt -= 4;
        }
    }
