   float32_t accum=0.0f, tmpA, tmpB,diff,sum;
   uint32_t blkCnt;
   float32x4_t a,b,c,accumV;
   float32x2_t accumV2;
   uint32x4_t   isZeroV;
   float32x4_t zeroV = vdupq_n_f32(0.0f);

