    float64_t pwra,pwrb,dot,tmp;

    arm_power_f64(pA, blockSize, &pwra);
    arm_power_f64(pB, blockSize, &pwrb);

    arm_dot_prod_f64(pA,pB,blockSize,&dot);

    tmp = sqrt(pwra * pwrb);
    return(1. - dot / tmp);

}

