        /* sub and then store the results in the destination buffer. */
        vecA = vld1q(pSrcAVec); 
        pSrcAVec += 4;
        vecB = vld1q(pSrcBVec); 
        pSrcBVec += 4;
        vecDst = vsubq(vecA, vecB);
        vst1q(pDataDst, vecDst);  
