#include "dsp/statistics_functions_f16.h"

/**
  @ingroup groupStats
 */

/**
  @addtogroup MSE
  @{
 */

/**
  @brief         Mean square error between two half floating point vectors.
  @param[in]     pSrcA       points to the first input vector
  @param[in]     pSrcB       points to the second input vector
  @param[in]     blockSize   number of samples in input vector
  @param[out]    result      mean square error
  @return        none
 */

#if !defined(ARM_MATH_AUTOVECTORIZE)

#if defined(ARM_MATH_MVE_FLOAT16)
#include "arm_helium_utils.h"

void arm_mse_f16(
    const float16_t * pSrcA,
    const float16_t * pSrcB,
    uint32_t    blockSize,
    float16_t * result)

{
    float16x8_t vecA, vecB;
    float16x8_t vecSum;
    uint32_t blkCnt; 
    _Float16 sum = 0.0f16;  
    vecSum = vdupq_n_f16(0.0f16);

    blkCnt = (blockSize) >> 3;
    while (blkCnt > 0U)
    {
        vecA = vld1q(pSrcA);
        pSrcA += 8;

        vecB = vld1q(pSrcB);
        pSrcB += 8;

        vecA = vsubq(vecA, vecB);

        vecSum = vfmaq(vecSum, vecA, vecA);
        /*
         * Decrement the blockSize loop counter
         */
        blkCnt --;
    }

    blkCnt = (blockSize) & 7;
    if (blkCnt > 0U)
    {
        mve_pred16_t p0 = vctp16q(blkCnt);
        vecA = vld1q(pSrcA);
        vecB = vld1q(pSrcB);

        vecA = vsubq(vecA, vecB);
        vecSum = vfmaq_m(vecSum, vecA, vecA, p0);
    }

    sum = vecAddAcrossF16Mve(vecSum);

    /* Store result in destination buffer */
    *result = (_Float16)sum / (_Float16)blockSize;

}

#endif

#endif /*#if !defined(ARM_MATH_AUTOVECTORIZE)*/

#if defined(ARM_FLOAT16_SUPPORTED)

#if (!defined(ARM_MATH_MVE_FLOAT16)) || defined(ARM_MATH_AUTOVECTORIZE)

void arm_mse_f16(
    const float16_t * pSrcA,
    const float16_t * pSrcB,
    uint32_t    blockSize,
    float16_t * result)

{
  uint32_t blkCnt;                               /* Loop counter */
  _Float16 inA, inB;
  _Float16 sum = 0.0f16;                          /* Temporary return variable */
#if defined (ARM_MATH_LOOPUNROLL)
  blkCnt = (blockSize) >> 3;


  while (blkCnt > 0U)
  {
    inA = *pSrcA++; 
    inB = *pSrcB++;
    inA = (_Float16)inA - (_Float16)inB;
    sum += (_Float16)inA * (_Float16)inA;

    inA = *pSrcA++; 
    inB = *pSrcB++;
    inA = (_Float16)inA - (_Float16)inB;
    sum += (_Float16)inA * (_Float16)inA;

    inA = *pSrcA++; 
    inB = *pSrcB++;
    inA = (_Float16)inA - (_Float16)inB;
    sum += (_Float16)inA * (_Float16)inA;

    inA = *pSrcA++; 
    inB = *pSrcB++;
    inA = (_Float16)inA - (_Float16)inB;
    sum += (_Float16)inA * (_Float16)inA;

    inA = *pSrcA++; 
